package ngl.relay.core;
import java.util.*;
public final class ContextBuilder {public static final class Assembled{public final String text;public final boolean compacted;public final List<String>sourceIds,compactedIds;Assembled(String t,boolean c,List<String>s,List<String>x){text=t;compacted=c;sourceIds=s;compactedIds=x;}}private final int budgetChars;public ContextBuilder(int b){budgetChars=Math.max(1000,b);}private static boolean protective(Artifact a){return a.type==Artifact.Type.HUMAN_INPUT||a.type==Artifact.Type.HUMAN_DECISION||a.type==Artifact.Type.DELIBERATION||a.type==Artifact.Type.SYNTHESIS;}private static String entry(Artifact a,boolean compact){String h="\n--- artifact "+a.id+" ["+a.type.wire+" stage "+a.stage+" "+a.provider+(a.model==null?"":" "+a.model)+"] ---\n";if(!compact)return h+a.content+"\n";String x=a.content==null?"":a.content.replaceAll("\\s+"," ").trim();if(x.length()>120)x=x.substring(0,117)+"...";return h+"[COMPACTED; full content preserved by artifact id] "+x+"\n";}public Assembled assemble(String caseId,CaseStore store,String originalInputId,List<Artifact> artifacts,String task){StringBuilder b=new StringBuilder();b.append(task==null?"":task);List<String>src=new ArrayList<>(),compact=new ArrayList<>();for(Artifact a:artifacts){src.add(a.id);String e=entry(a,false);if(b.length()+e.length()<=budgetChars||protective(a))b.append(e);else{compact.add(a.id);b.append(entry(a,true));}}if(b.length()>budgetChars){String s=b.toString();b.setLength(0);b.append(s.substring(Math.max(0,s.length()-budgetChars)));}return new Assembled(b.toString(),!compact.isEmpty(),Collections.unmodifiableList(src),Collections.unmodifiableList(compact));}}
